BEGIN;
DELETE FROM disbursement_daily WHERE disb_date IN ('2026-04-02','2026-04-04','2026-04-06','2026-04-07','2026-04-08','2026-04-09','2026-04-10','2026-04-13','2026-04-15','2026-04-16','2026-04-17','2026-04-18','2026-04-20','2026-04-21');
CREATE TEMP TABLE _disb_stage (disb_date date, branch_name text, emp_id text, officer_name text, product_name text, disb_count int, disb_amount numeric);
-- Match by emp_id (unique) — branch_name spelling varies between source CSV and master.
SELECT s.disb_date,
       COALESCE(UPPER(em.region_name), 'UNKNOWN'),
       COALESCE(UPPER(em.region_name), 'UNKNOWN'),
       s.branch_name, s.emp_id, s.officer_name, s.product_name, s.disb_count, s.disb_amount
FROM _disb_stage s
LEFT JOIN employee_master em ON em.emp_id = s.emp_id;
COMMIT;
